import React, { useState } from 'react';
import { ChevronDown, CheckCircle2, Sparkles, ExternalLink } from 'lucide-react';

const initialFaq = [
  {
    id: 1,
    title: 'How do I make a reservation?',
    content:
      'Simply fill out the form below or call us directly. Our team will confirm your table and preferences.',
    isOpen: false,
  },
  {
    id: 2,
    title: 'Do you offer delivery?',
    content: 'Yes, for select dishes. Click the “Order Now” button to access our menu and delivery options.',
    isOpen: false,
  },
  {
    id: 3,
    title: 'What is your cancellation policy?',
    content:
      'We require 24-hour notice for cancellations to avoid a 10% cancellation fee. Please contact us directly.',
    isOpen: false,
  },
  {
    id: 4,
    title: 'Are your dishes gluten-free?',
    content:
      'Absolutely! We have a dedicated gluten-free chef. Please inform your server of your dietary preferences.',
    isOpen: false,
  },
  {
    id: 5,
    title: 'Do you offer any happy hour specials?',
    content:
      'Yes, every weekday from 4-6pm enjoy a 25% discount on all appetizers and cocktails. Must be present.',
    isOpen: false,
  },
];

export default function Faq() {
  const [activeId, setActiveId] = useState(null);

  const toggle = (id) => {
    setActiveId((prev) => (prev === id ? null : id));
  };

  return (
    <div className="w-full max-w-7xl mx-auto p-4 sm:p-6 lg:p-8 bg-slate-950 text-slate-100 font-sans">
      <div className="text-center max-w-md mx-auto mb-12">
        <h2 className="text-2xl sm:text-3xl font-bold tracking-tight text-indigo-400 border-b-4 pb-2 border-indigo-500">Frequently Asked Questions</h2>
        <p className="mt-4 text-sm sm:text-base text-slate-400">Explore our answers to the most common questions about our restaurant.</p>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
        {initialFaq.map((faq) => (
          <div
            key={faq.id}
            className="group relative rounded-2xl bg-white/5 border border-white/10 p-6 transition-all duration-300 hover:shadow-2xl hover:shadow-indigo-500/10"
          >
            <div className="flex justify-between items-start mb-4">
              <div className="text-xl font-semibold text-slate-200 flex items-start gap-2">
                {faq.title}
                <span className="text-sm text-indigo-400 group-hover:text-indigo-300 transition-colors duration-200"><Sparkles className="w-4 h-4" /></span>
              </div>
              <button
                onClick={() => toggle(faq.id)}
                className="p-2 rounded-xl bg-white/5 border border-white/10 text-slate-400 hover:text-slate-200 hover:bg-white/10 transition-colors duration-200"
              >
                <ChevronDown className={`w-5 h-5 transition-transform ${activeId === faq.id ? 'rotate-180' : 'rotate-0'}`} />
              </button>
            </div>

            {activeId === faq.id && (
              <div className="text-slate-300 text-sm sm:text-base max-w-md mx-auto mt-4">
                {faq.content}
                <div className="flex items-center gap-2 mt-6">
                  <div className="bg-emerald-500/20 p-2 rounded-xl border border-emerald-500/30 text-emerald-400"><CheckCircle2 className="w-4 h-4" /></div>
                  <p className="text-sm text-slate-400">Order Now <a href="#menu" className="text-indigo-400 hover:underline"><ExternalLink className="w-3 h-3 inline-block" /></a></p>
                </div>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

