export default function Menu() {
  const [searchQuery, setSearchQuery] = useState('');
  const [filterCategory, setFilterCategory] = useState('All');
  const [selectedItems, setSelectedItems] = useState([]);

  const handleSelect = (item) => {
    if (selectedItems.includes(item.id)) {
      setSelectedItems(selectedItems.filter(id => id !== item.id));
    } else {
      setSelectedItems([item.id, ...selectedItems]);
    }
  };

  const filteredMenu = MOCK_MENU.filter(item => {
    const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesFilter = filterCategory === 'All' || item.category === filterCategory;
    return matchesSearch && matchesFilter;
  });

  return (
    <div className="min-h-full bg-slate-950 text-slate-100 font-sans antialiased">
      {/* Decorative background overlay */}
      <div className="fixed inset-0 z-0 bg-white/10 backdrop-blur-xl animate-pulse" />

      <header className="bg-white/10 backdrop-blur-xl shadow-sm border-b border-slate-800/50 px-4 sm:px-6 py-4 flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-slate-100 flex items-center gap-2">
            <Sparkles className="w-5 h-5 text-amber-400 animate-pulse" />
            {`Grilled & Steamed`}
          </h1>
          <p className="text-sm text-slate-400">Experience the fusion of high heat and traditional flavors.</p>
        </div>
        <button className="inline-flex items-center gap-2 px-3.5 py-1.5 rounded-lg bg-white/5 border border-white/10 text-slate-400 hover:text-slate-200 hover:bg-white/10 transition-colors duration-300">
          <Search className="w-4 h-4" />
          <span>Search Menu</span>
        </button>
      </header>

      {/* Main menu card grid */}
      <div className="max-w-7xl mx-auto py-20 px-4 sm:px-6">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredMenu.map((item) => (
            <div
              key={item.id}
              className="group relative overflow-hidden rounded-2xl bg-slate-800/60 border border-white/10 transition-all duration-300 hover:scale-[1.02] hover:shadow-2xl"
            >
              {/* Background overlay */}
              <div className="absolute inset-0 bg-gradient-to-br from-indigo-500 via-purple-500 to-pink-500 opacity-40 group-hover:opacity-0 transition-opacity duration-300" />

              {/* Top overlay with border */}
              <div className="relative border-b border-white/20 h-24 group-hover:scale-105 transition-transform duration-500 group-hover:bg-white/5 group-hover:scale-[1.01]">
                <img
                  src={item.image}
                  alt={item.name}
                  className="object-cover w-full h-full"
                  loading="lazy"
                  decoding="async"
                />
              </div>

              {/* Bottom content stack */}
              <div className="p-6 flex flex-col justify-between h-full">
                <div>
                  <h3 className="text-lg font-semibold text-slate-100 mb-2 group-hover:text-amber-400 transition-colors duration-300">
                    {item.name}
                  </h3>
                  <p className="text-sm text-slate-400">{item.description}</p>
                  <p className="text-sm font-semibold mt-2 text-amber-400 flex items-center gap-1">
                    {item.price.toFixed(2)} <span className="text-xs font-normal text-slate-500">USD</span>
                  </p>
                </div>
                <div className="mt-6 flex items-center gap-2">
                  {selectedItems.includes(item.id) ? (
<>
                    <button
                      onClick={() => handleSelect(item)}
                      disabled={selectedItems.length === 0}
                      className="inline-flex items-center gap-1 px-3.5 py-1.5 rounded-lg bg-white/10 border border-white/20 text-slate-400 hover:text-slate-200 hover:bg-white/20 transition-colors duration-300"
                    >
                      <Check className="w-3 h-3" />
                      <span>Added</span>
                    </button>
                  </>) : (
<>
                    <button
                      onClick={() => handleSelect(item)}
                      className="inline-flex items-center gap-1 px-3.5 py-1.5 rounded-lg bg-white/10 border border-white/20 text-slate-400 hover:text-amber-400 hover:bg-white/20 transition-colors duration-300"
                    >
                      <Utensils className="w-3 h-3" />
                      <span>Add to Cart</span>
                    </button>
                  </>)}
                  <p className="text-xs text-slate-500">{item.time}</p>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Filter & Search Bar */}
      <div className="max-w-7xl mx-auto py-10 px-4 sm:px-6">
        <div className="relative overflow-hidden rounded-2xl bg-white/5 border border-white/10 backdrop-blur-md shadow-md shadow-slate-900/70 p-4 sm:p-6 flex flex-col sm:flex-row items-center justify-between gap-4">
          <div className="flex flex-wrap items-center gap-2">
