                key={f.value}
                onClick={() => setFilterCategory(f.value)}
                className={`py-2 px-3 rounded-lg text-xs font-medium transition-colors ${
                  filterCategory === f.value ? "bg-white/10 text-white border-white/20" : "bg-white/5 text-slate-400 border-white/10 hover:text-slate-200 hover:bg-white/10"
                }`}
              >
                {f.label}
              </button>
            ))}
          </div>
          <div className="flex flex-wrap items-center gap-2">
            <button className="inline-flex items-center gap-1 px-3.5 py-1.5 rounded-lg bg-white/10 border border-white/20 text-slate-400 hover:text-slate-200 hover:bg-white/20 transition-colors duration-300">
              <Filter className="w-3 h-3" />
              <span>Filter</span>
            </button>
            <button className="inline-flex items-center gap-1 px-3.5 py-1.5 rounded-lg bg-white/10 border border-white/20 text-slate-400 hover:text-slate-200 hover:bg-white/20 transition-colors duration-300">
              <Search className="w-3 h-3" />
              <span>Search</span>
            </button>
          </div>
        </div>
      </div>

      {/* Footer */}
      <footer className="max-w-7xl mx-auto py-20 px-4 sm:px-6 text-center">
        <div className="w-full mx-auto max-w-sm">
          <p className="text-sm text-slate-500 mb-4">Ready to order? Drop us a line or simply walk in. We're always here to serve.</p>
          <div className="flex gap-4 justify-center mb-6">
            <button className="inline-flex items-center gap-2 px-4 py-2 rounded-lg bg-white/10 border border-white/20 text-slate-400 hover:text-slate-200 hover:bg-white/20 transition-colors duration-300">
              <MapPin className="w-4 h-4" />
              <span>Reservation</span>
            </button>
            <button className="inline-flex items-center gap-2 px-4 py-2 rounded-lg bg-white/10 border border-white/20 text-slate-400 hover:text-slate-200 hover:bg-white/20 transition-colors duration-300">
