import React, { useState } from 'react';
import { X, CheckCircle2, Calendar, Clock, Users, MapPin, Phone, Mail, Sparkles, User } from 'lucide-react';

const initialForm = {
  name: '',
  email: '',
  phone: '',
  guests: 4,
  date: '2023-10-15',
  time: '19:00',
};

export default function Reservations() {
  const [formData, setFormData] = useState(initialForm);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
    setIsSubmitting(true);
    setTimeout(() => {
      setIsSubmitting(false);
      setIsSuccess(true);
      setFormData(initialForm);
    }, 1200);
  };

  const [isTimeLocked, setIsTimeLocked] = useState(false);
  const [lockedTimes, setLockedTimes] = useState(['18:00', '18:30', '19:00']);

  const toggleTimeLock = () => {
    setIsTimeLocked(!isTimeLocked);
    if (!isTimeLocked) {
      setLockedTimes(['18:00', '18:30', '19:00']);
    } else {
      setLockedTimes([]);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex items-center justify-center p-4 sm:p-6 lg:p-8">
      <div className="w-full max-w-2xl mx-auto relative z-10 bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl p-8 shadow-2xl transition-all duration-500 hover:shadow-3xl">

        {/* Decorative Gradients and Header */}
        <div className="absolute -top-40 -right-40 w-96 h-96 bg-gradient-to-br from-indigo-500 via-purple-500 to-pink-500 opacity-20 rounded-full blur-3xl pointer-events-none" />
        <div className="relative z-20 mb-8">
          <h2 className="text-3xl sm:text-4xl font-bold tracking-tight text-slate-900 text-center">Find Your Seat</h2>
          <p className="mt-2 text-slate-400 text-sm max-w-md mx-auto">Reserve your table or send us a direct message for special requests.</p>
        </div>

        {/* Card Stack */}
        <div className="space-y-6 sm:space-y-8">

          {/* Grille & Bar */}
          <div className="relative overflow-hidden rounded-2xl bg-slate-900/30 p-6 shadow-inner transition-all duration-300 hover:scale-[1.01] hover:shadow-indigo-500/10">
            <div className="absolute -top-24 -left-24 w-48 h-48 bg-indigo-600/20 rounded-full blur-3xl pointer-events-none" />
            <div className="relative z-10">
              <h3 className="text-xl font-semibold tracking-tight text-slate-100 mb-2">Grill & Bar</h3>
              <p className="text-sm text-slate-400 mb-4">Our signature grills and craft cocktails await.</p>
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                <div className="p-3 rounded-xl bg-slate-900/50 border border-slate-800 text-slate-300 flex items-center gap-2">
                  <Sparkles className="w-4 h-4 text-indigo-400" />
                  <span>Prime Cuts</span>
                </div>
                <div className="p-3 rounded-xl bg-slate-900/50 border border-slate-800 text-slate-300 flex items-center gap-2">
                  <Sparkles className="w-4 h-4 text-indigo-400" />
                  <span>Shaken & Stirred</span>
                </div>
                <div className="p-3 rounded-xl bg-slate-900/50 border border-slate-800 text-slate-300 flex items-center gap-2">
                  <Sparkles className="w-4 h-4 text-indigo-400" />
                  <span>Wine & Vines</span>
                </div>
                <div className="p-3 rounded-xl bg-slate-900/50 border border-slate-800 text-slate-300 flex items-center gap-2">
                  <Sparkles className="w-4 h-4 text-indigo-400" />
                  <span>Sushi & Sashimi</span>
                </div>
              </div>
            </div>
          </div>

          {/* Table Reservation Form */}
          <div className="relative overflow-hidden rounded-2xl bg-slate-900/30 p-6 shadow-inner transition-all duration-300 hover:scale-[1.01] hover:shadow-indigo-500/10">
            <div className="absolute -top-24 -left-24 w-48 h-48 bg-indigo-600/20 rounded-full blur-3xl pointer-events-none" />
            <div className="relative z-10">
              <h3 className="text-xl font-semibold tracking-tight text-slate-100 mb-2">Table Reservation</h3>
              <p className="text-sm text-slate-400 mb-4">Secure your perfect table for a memorable dining experience.</p>
              <form onSubmit={handleSubmit} className="space-y-4 sm:space-y-6">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <div className="relative">
                    <label htmlFor="name" className="sr-only">Full Name</label>
                    <input 
                      type="text" 
                      id="name" 
                      value={formData.name} 
                      onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                      required 
                      placeholder="John Doe"
                      className="w-full bg-slate-900/40 border border-slate-800 rounded-lg p-3 text-slate-300 placeholder:text-slate-400 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all duration-200"
                    />
                    <span className="absolute inset-y-0 left-2 flex items-center pl-2 text-slate-400"><User /></span>
                  </div>
                  <div className="relative">
                    <label htmlFor="email" className="sr-only">Email Address</label>
                    <input 
                      type="email" 
                      id="email" 
                      value={formData.email} 
                      onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                      required 
                      placeholder="john.doe@example.com"
                      className="w-full bg-slate-900/40 border border-slate-800 rounded-lg p-3 text-slate-300 placeholder:text-slate-400 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all duration-200"
                    />
                    <span className="absolute inset-y-0 left-2 flex items-center pl-2 text-slate-400"><Mail /></span>
                  </div>
                </div>
                <div className="relative">
                  <label htmlFor="guests" className="sr-only">Number of Guests</label>
                  <select 
                    id="guests" 
                    value={formData.guests} 
                    onChange={(e) => setFormData({ ...formData, guests: Number(e.target.value) })}
                    className="w-full bg-slate-900/40 border border-slate-800 rounded-lg p-3 text-slate-300 placeholder:text-slate-400 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all duration-200"
                  >
                    {[2, 4, 6, 8, 10].map(n => (
                      <option key={n} value={n}>{n} guests</option>
                    ))}
                  </select>
                  <span className="absolute inset-y-0 left-2 flex items-center pl-2 text-slate-400"><Users /></span>
                </div>
                <div className="relative sm:flex sm:items-center">
                  <div className="relative flex-1">
                    <label htmlFor="date" className="sr-only">Date</label>
                    <input 
                      type="date" 
                      id="date" 
                      value={formData.date} 
                      min={new Date().toISOString().split('T')[0]}
                      onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                      required 
                      className="w-full bg-slate-900/40 border border-slate-800 rounded-lg p-3 text-slate-300 placeholder:text-slate-400 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all duration-200"
                    />
                    <span className="absolute inset-y-0 left-2 flex items-center pl-2 text-slate-400"><Calendar /></span>
                  </div>
                  <div className="relative sm:ml-4 sm:shrink-0">
                    <label htmlFor="time" className="sr-only">Time</label>
                    <input 
                      type="time" 
                      id="time" 
                      value={formData.time} 
                      onChange={(e) => setFormData({ ...formData, time: e.target.value })}
                      required 
                      className="w-full bg-slate-900/40 border border-slate-800 rounded-lg p-3 text-slate-300 placeholder:text-slate-400 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all duration-200"
                    />
                    <span className="absolute inset-y-0 right-2 flex items-center pr-2 text-slate-400"><Clock /></span>
                  </div>
                </div>
                {isTimeLocked && (
                  <div className="text-sm text-slate-400 mt-2">
                    <p>Please request a time outside of peak dining hours.</p>
                    <p className="text-indigo-400 cursor-pointer hover:text-indigo-300" onClick={toggleTimeLock}>Unlock Available Times</p>
                  </div>
                )}
                {!isTimeLocked && (
                  <div className="text-sm text-slate-400 mt-2">
                    <p>Times available at your selected date:</p>
                    <div className="flex gap-2 mt-1">
                      {['18:30', '19:30', '20:30', '21:30', '22:30'].map(t => (
                        <div key={t} className="py-1 px-2 rounded-full bg-indigo-500/10 border border-indigo-500/20 text-indigo-400 text-xs font-medium hover:bg-indigo-500/20 transition-colors duration-200">
                          {t}
                        </div>
                      ))}
                    </div>
                  </div>
                )}
                <button 
                  type="submit" 
                  disabled={isSubmitting}
                  className="w-full sm:w-fit inline-flex items-center justify-center px-6 py-3 text-sm font-semibold tracking-wide text-white transition-all duration-200 bg-indigo-600 hover:bg-indigo-700 border border-indigo-600/30 rounded-xl shadow-lg hover:shadow-xl backdrop-blur-xl text-slate-100 hover:backdrop-brightness-90"
                >
                  {isSubmitting ? <div className="w-5 h-5 animate-pulse text-white" /> : "Reserve Table"}
                </button>
              </form>
              {isSuccess && (
                <div className="mt-6 p-4 rounded-2xl bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 flex items-center gap-2">
                  <CheckCircle2 className="w-5 h-5" />
                  <p>Reservation Confirmed!</p>
                </div>
              )}
            </div>
          </div>

          {/* Location & Contact */}
          <div className="relative overflow-hidden rounded-2xl bg-slate-900/30 p-6 shadow-inner transition-all duration-300 hover:scale-[1.01] hover:shadow-indigo-500/10">
            <div className="absolute -top-24 -right-24 w-48 h-48 bg-indigo-600/20 rounded-full blur-3xl pointer-events-none" />
            <div className="relative z-10">
              <h3 className="text-xl font-semibold tracking-tight text-slate-100 mb-2">Find Us</h3>
              <p className="text-sm text-slate-400 mb-4">Join us at our elegant rooftop venue.</p>
              <div className="flex flex-col sm:flex-row sm:items-center gap-3 mb-6">
                <div className="p-3 rounded-xl bg-slate-900/20 border border-slate-800 text-slate-300 flex items-center gap-2">
                  <MapPin className="w-4 h-4 text-emerald-500" />
                  <p>123 S River Street, New York, NY 10001</p>
                </div>
                <div className="p-3 rounded-xl bg-slate-900/20 border border-slate-800 text-slate-300 flex items-center gap-2">
                  <Phone className="w-4 h-4 text-emerald-500" />
                  <p>(212) 555-1234</p>
                </div>
              </div>
              <a href="mailto:reservations@thebusiness.com" className="inline-flex items-center gap-2 text-slate-300 hover:text-slate-100 transition-colors duration-200">
                <Mail className="w-5 h-5" /> reservations@thebusiness.com
              </a>
            </div>
